B.a_d=new A.b8("gecici_08",B.dh,"Kar\u015f\u0131 taraf dinlenmeden (yoklu\u011funda) verilen ihtiyati tedbir kararlar\u0131na kar\u015f\u0131, itiraz hakk\u0131 olanlar karar\u0131n uygulanmas\u0131 s\u0131ras\u0131nda haz\u0131r bulunmuyorlarsa, tedbirin uygulanmas\u0131na ili\u015fkin tutana\u011f\u0131n tebli\u011finden itibaren en ge\xe7 ne kadar s\xfcre i\xe7inde itiraz edebilirler?",B.ml,0,"HMK m. 394/2 uyar\u0131nca kar\u015f\u0131 taraf dinlenmeden verilmi\u015f olan ihtiyati tedbir kararlar\u0131na itiraz s\xfcresi, karar\u0131n uyguland\u0131\u011f\u0131na ili\u015fkin tutana\u011f\u0131n tebli\u011finden itibaren bir haftad\u0131r.")
B.Tz=s(["\u0130htiyati tedbir","\u0130htiyati haciz","Delil tespiti","\u0130htiyari dava arkada\u015fl\u0131\u011f\u0131"],t.s)
B.a_r=new A.b8("gecici_09",B.dh,"G\xf6r\xfclmekte olan veya ileride a\xe7\u0131lacak bir davada ispat vas\u0131tas\u0131 olarak kullan\u0131lacak olan delillerin kaybolmas\u0131 veya g\xf6sterilmesinin \xe7ok zorla\u015fmas\u0131 ihtimali kar\u015f\u0131s\u0131nda ba\u015fvurulan ge\xe7ici hukuki koruma kurumu a\u015fa\u011f\u0131dakilerden hangisidir?",B.Tz,2,"HMK m. 400 uyar\u0131nca, taraflar hen\xfcz inceleme s\u0131ras\u0131 gelmemi\u015f olan veya ileride a\xe7\u0131lacak davada ileri s\xfcr\xfclecek delillerin kaybolaca\u011f\u0131 veya ileri s\xfcr\xfclmesinin zorla\u015faca\u011f\u0131 ihtimali varsa delil tespiti isteyebilir.")
B.a_g=new A.b8("kanun_08",B.dj,"Hukuk mahkemeleri taraf\u0131ndan verilen nihai kararlara kar\u015f\u0131, karar\u0131n usul\xfcne uygun tebli\u011finden itibaren kural olarak ka\xe7 hafta i\xe7inde istinaf yoluna ba\u015fvurulabilir?",B.ml,1,"HMK m. 345 uyar\u0131nca istinaf yoluna ba\u015fvuru s\xfcresi, karar\u0131n usul\xfcne uygun olarak taraflara tebli\u011finden itibaren iki haftad\u0131r.")
B.UY=s(["Miktar veya de\u011feri temyiz s\u0131n\u0131r\u0131n\u0131 a\u015fan alacak davalar\u0131","Soyba\u011f\u0131na ili\u015fkin kararlar","\xc7eki\u015fmesiz yarg\u0131 i\u015flerinde verilen kararlar","Ta\u015f\u0131nmaz \xfczerindeki ayni haklara ili\u015fkin kararlar"],t.s)
B.a_v=new A.b8("kanun_09",B.dj,"B\xf6lge adliye mahkemesi hukuk dairelerinden verilen a\u015fa\u011f\u0131daki kararlardan hangisine kar\u015f\u0131 kural olarak temyiz yoluna ba\u015fvurulamaz?",B.UY,2,"HMK m. 362/1-\xe7 bendine g\xf6re \xe7eki\u015fmesiz yarg\u0131 i\u015flerinde verilen b\xf6lge adliye mahkemesi kararlar\u0131 kesin olup bu kararlara kar\u015f\u0131 temyiz yoluna ba\u015fvurulamaz.")
B.TH=s(["Feragat, h\xfck\xfcm kesinle\u015finceye kadar her zaman yap\u0131labilir.","Feragatin ge\xe7erlili\u011fi kar\u015f\u0131 taraf\u0131n veya mahkemenin kabul\xfcne ba\u011fl\u0131d\u0131r.","Feragat, kesin h\xfck\xfcm gibi hukuki sonu\xe7 do\u011furur.","\u015earta ba\u011fl\u0131 feragat kural olarak ge\xe7erli de\u011fildir."],t.s)
B.a_6=new A.b8("taraf_08",B.di,'Davac\u0131n\u0131n talep sonucundan k\u0131smen veya tamamen vazge\xe7mesi olan "feragat" kurumu ile ilgili a\u015fa\u011f\u0131dakilerden hangisi yanl\u0131\u015ft\u0131r?',B.TH,1,"HMK m. 309 uyar\u0131nca feragat ve kabul, kar\u015f\u0131 taraf\u0131n veya mahkemenin muvafakatine ba\u011fl\u0131 de\u011fildir; tek tarafl\u0131 irade beyan\u0131yla derhal sonu\xe7 do\u011furur.")
B.JH=new A.i(1,0.8941176470588236,0.6039215686274509,0.8235294117647058,B.d)
B.a__=new A.oa("H\xfck\xfcm ve Kesin H\xfck\xfcm",B.JH,5,"hukumKesinHuku")
B.QD=s(["Sadece taraflar\u0131n\u0131n","Sadece dava sebeplerinin","Taraflar\u0131n\u0131n, dava sebeplerinin ve ilk davan\u0131n h\xfck\xfcm f\u0131kras\u0131 ile ikinci davan\u0131n talep sonucunun","Sadece mahkemelerinin"],t.s)
B.a_E=new A.b8("hukum_01",B.a__,"Bir davada verilen karar\u0131n ba\u015fka bir davada maddi anlamda kesin h\xfck\xfcm te\u015fkil edebilmesi i\xe7in her iki davan\u0131n hangi unsurlar\u0131n\u0131n ayn\u0131 olmas\u0131 zorunludur?",B.QD,2,"HMK m. 303/1 uyar\u0131nca maddi anlamda kesin h\xfck\xfcmden s\xf6z edilebilmesi i\xe7in her iki davan\u0131n taraflar\u0131n\u0131n, dava sebeplerinin (vak\u0131alar\u0131n) ve ilk davan\u0131n h\xfck\xfcm f\u0131kras\u0131 ile ikinci davan\u0131n talep sonucunun ayn\u0131 olmas\u0131 gerekir.")
B.QH=s(["Eksikli\u011fi gidermesi i\xe7in davac\u0131ya bir haftal\u0131k kesin s\xfcre verir.","Davay\u0131 esastan reddeder.","Davay\u0131, dava \u015fart\u0131 yoklu\u011fu sebebiyle usulden reddeder.","Davay\u0131 durdurur ve taraflar\u0131 arabulucuya g\xf6nderir."],t.s)
B.a_3=new A.b8("arabulucu_07",B.eS,"Kanunlarda arabuluculu\u011fa ba\u015fvurulmu\u015f olmas\u0131n\u0131n dava \u015fart\u0131 olarak \xf6ng\xf6r\xfcld\xfc\u011f\xfc durumlarda, davac\u0131 arabulucuya ba\u015fvurmadan do\u011frudan dava a\xe7arsa mahkeme nas\u0131l bir karar verir?",B.QH,2,"6325 say\u0131l\u0131 Hukuk Uyu\u015fmazl\u0131klar\u0131nda Arabuluculuk Kanunu m. 18/A-2 uyar\u0131nca, arabulucuya ba\u015fvurulmadan dava a\xe7\u0131ld\u0131\u011f\u0131n\u0131n anla\u015f\u0131lmas\u0131 halinde herhangi bir i\u015flem yap\u0131lmaks\u0131z\u0131n davan\u0131n, dava \u015fart\u0131 yoklu\u011fu sebebiyle usulden reddine karar verilir.")
